import com.evolveum.midpoint.model.api.ModelAuditService
import com.evolveum.midpoint.model.api.TaskService
import com.evolveum.midpoint.model.impl.expr.SpringApplicationContextHolder
import com.evolveum.midpoint.xml.ns._public.common.audit_3.AuditEventRecordType
import com.evolveum.midpoint.xml.ns._public.common.audit_3.AuditEventTypeType
import com.evolveum.midpoint.xml.ns._public.common.common_3.OperationResultStatusType
import com.evolveum.midpoint.xml.ns._public.common.common_3.TaskExecutionStateType
import com.evolveum.midpoint.xml.ns._public.common.common_3.TaskType

def maxAgeMs = 7L * 24 * 3600 * 1000
def result = midpoint.currentResult
def oid = input.oid
try {
    // Fresh read: the search that found this task may be minutes old.
    def t = midpoint.repositoryService.getObject(TaskType.class, oid, null, result).asObjectable()
    if (t.executionState != TaskExecutionStateType.SUSPENDED
            || t.resultStatus != OperationResultStatusType.FATAL_ERROR) {
        log.info('LiveSync watchdog: leaving {}: it is no longer suspended after a failed run', t.name)
        return
    }
    def started = t.lastRunStartTimestamp
    def finished = t.lastRunFinishTimestamp
    if (started == null || finished == null) {
        log.info('LiveSync watchdog: leaving {}: no finished run on record', t.name)
        return
    }
    if (finished.toGregorianCalendar().timeInMillis < System.currentTimeMillis() - maxAgeMs) {
        log.info('LiveSync watchdog: leaving {}: its failed run finished at {}, more than 7 days ago', t.name, finished)
        return
    }
    // midPoint audits anything a person does to a task with the task as
    // target, and its own suspend after a failed run without one. Reads,
    // resumes and run-now ask for a running task, and this watchdog's own
    // resume is one of them, so they are ignored. Any other record means a
    // person acted on the task, and the watchdog leaves it alone.
    def query = prismContext.queryFor(AuditEventRecordType.class)
            .item(AuditEventRecordType.F_TARGET_REF).ref(oid)
            .and().item(AuditEventRecordType.F_TIMESTAMP).ge(started)
            .and().not().item(AuditEventRecordType.F_EVENT_TYPE).eq(AuditEventTypeType.GET_OBJECT)
            .and().not().item(AuditEventRecordType.F_EVENT_TYPE).eq(AuditEventTypeType.RESUME_TASK)
            .and().not().item(AuditEventRecordType.F_EVENT_TYPE).eq(AuditEventTypeType.RUN_TASK_IMMEDIATELY)
            .build()
    // The beans are looked up by type, because getBean(Class) on this
    // holder looks for a bean named after the class, and no bean has that name.
    def spring = SpringApplicationContextHolder.getApplicationContext()
    def touched = spring.getBean(ModelAuditService.class)
            .countObjects(query, null, midpoint.currentTask, result)
    if (touched != 0) {
        log.info('LiveSync watchdog: leaving {}: {} audit record(s) since its last run started at {} show a person acted on it',
                t.name, touched, started)
        return
    }
    log.info('LiveSync watchdog: resuming {}: midPoint suspended it after the run that started at {} failed, and nobody has acted on it since',
            t.name, started)
    spring.getBean(TaskService.class).resumeTask(oid, midpoint.currentTask, result)
} catch (Throwable e) {
    log.error('LiveSync watchdog: leaving {} suspended, the check failed: {}', oid, e.message, e)
    throw e
}
